using AshkanCMS.Data; using AshkanCMS.Models; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore;
namespace AshkanCMS.Areas.Admin.Controllers; [Area("Admin"),Authorize]
public class MenusController(AppDbContext db):Controller { public async Task<IActionResult> Index()=>View(await db.MenuItems.OrderBy(x=>x.SortOrder).ToListAsync()); [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Add(MenuItem x){if(ModelState.IsValid){db.MenuItems.Add(x);await db.SaveChangesAsync();}return RedirectToAction(nameof(Index));} [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Toggle(int id){var x=await db.MenuItems.FindAsync(id);if(x!=null){x.IsVisible=!x.IsVisible;await db.SaveChangesAsync();}return RedirectToAction(nameof(Index));} [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Delete(int id){var x=await db.MenuItems.FindAsync(id);if(x!=null){db.Remove(x);await db.SaveChangesAsync();}return RedirectToAction(nameof(Index));}}
